import 'dart:convert';
import 'dart:io';
import 'package:flutter/services.dart' show rootBundle;
import 'package:sqflite/sqflite.dart';
import 'package:path/path.dart';
import 'package:path_provider/path_provider.dart';
import 'package:sqflite_common_ffi/sqflite_ffi.dart';
import '../models/word.dart';
import '../utils/text_fold.dart';

class DatabaseHelper {
  static final DatabaseHelper _instance = DatabaseHelper._internal();
  factory DatabaseHelper() => _instance;
  DatabaseHelper._internal();

  // Both files are generated by tools/build_words.py. Declare the whole
  // assets/data/ folder in pubspec.yaml so both are bundled.
  static const String _seedAssetPath = 'assets/data/words.json';
  static const String _seedVersionPath = 'assets/data/words.version';
  static const String _metaSeedVersion = 'seed_version';

  // Bump this only when the TABLE STRUCTURE changes (and add a branch to
  // _onUpgrade). Changing the dictionary data does not need a bump: the seed
  // is re-synced automatically whenever words.version changes.
  static const int _schemaVersion = 2;

  static const int _searchLimit = 50;

  // Cache the Future, not the Database: if two screens ask for the database
  // while it is still opening (or the first-launch seed is still running),
  // they must share one initialization instead of starting two.
  Future<Database>? _databaseFuture;

  Future<Database> get database => _databaseFuture ??= _initDatabase();

  Future<Database> _initDatabase() async {
    // Initialize FFI for desktop platforms
    if (Platform.isLinux || Platform.isWindows || Platform.isMacOS) {
      databaseFactory = databaseFactoryFfi;
    }

    // Get appropriate path
    String dbPath;
    if (Platform.isLinux || Platform.isWindows || Platform.isMacOS) {
      final appDir = await getApplicationDocumentsDirectory();
      dbPath = join(appDir.path, 'dicionario_brunca.db');
    } else {
      dbPath = join(await getDatabasesPath(), 'dicionario_brunca.db');
    }

    final db = await openDatabase(
      dbPath,
      version: _schemaVersion,
      onCreate: (db, version) => _createSchema(db),
      onUpgrade: _onUpgrade,
    );

    await _syncSeed(db);
    return db;
  }

  // ---------------------------------------------------------------------
  // Schema
  // ---------------------------------------------------------------------

  Future<void> _createSchema(Database db) async {
    // Dictionary content. Replaced wholesale from the seed asset whenever
    // the seed version changes, so nothing the user does may live here.
    await db.execute('''
      CREATE TABLE entries(
        id TEXT PRIMARY KEY,
        brunca TEXT NOT NULL,
        variants TEXT NOT NULL DEFAULT '[]',
        homograph INTEGER,
        pos TEXT,
        posLabel TEXT,
        senses TEXT NOT NULL DEFAULT '[]',
        literal TEXT,
        examples TEXT NOT NULL DEFAULT '[]',
        phrases TEXT NOT NULL DEFAULT '[]',
        note TEXT,
        category TEXT,
        audioFile TEXT,
        s_head TEXT NOT NULL,
        s_gloss TEXT NOT NULL,
        s_other TEXT NOT NULL DEFAULT ''
      )
    ''');

    // User data, kept separate and keyed by the stable entry id so that
    // re-seeding (or fixing a transcription) never loses or shifts favorites.
    await db.execute('''
      CREATE TABLE favorites(
        entry_id TEXT PRIMARY KEY,
        added_at INTEGER NOT NULL
      )
    ''');

    await db.execute('''
      CREATE TABLE meta(
        key TEXT PRIMARY KEY,
        value TEXT
      )
    ''');
  }

  Future<void> _onUpgrade(Database db, int oldVersion, int newVersion) async {
    if (oldVersion < 2) {
      // v1 held five placeholder words with auto-increment ids and an
      // isFavorite column. Those rows can't be mapped onto real dictionary
      // entries, so v2 starts clean. (From v2 on, favorites live in their own
      // table and survive both migrations and re-seeds.)
      await db.execute('DROP TABLE IF EXISTS words');
      await _createSchema(db);
    }
    // Future migrations: add `if (oldVersion < 3) { ... }` blocks here.
  }

  // ---------------------------------------------------------------------
  // Seeding
  // ---------------------------------------------------------------------

  /// Loads the bundled dictionary into `entries` if (and only if) its
  /// version differs from the one already loaded. The version file is tiny,
  /// so the normal launch cost is reading one short string.
  Future<void> _syncSeed(Database db) async {
    final String bundledVersion =
        (await rootBundle.loadString(_seedVersionPath)).trim();

    final rows = await db.query(
      'meta',
      where: 'key = ?',
      whereArgs: [_metaSeedVersion],
    );
    final String? loadedVersion =
        rows.isEmpty ? null : rows.first['value'] as String?;
    if (loadedVersion == bundledVersion) return;

    // loadString decodes as UTF-8, so tone marks, ᵛ and n̈ arrive intact.
    final String jsonString = await rootBundle.loadString(_seedAssetPath);
    final List<dynamic> entries = jsonDecode(jsonString) as List<dynamic>;

    // One transaction: either the whole new dictionary is in, or the old one
    // is untouched. The favorites table is not modified here.
    await db.transaction((txn) async {
      await txn.delete('entries');
      final batch = txn.batch();
      for (final raw in entries) {
        batch.insert(
          'entries',
          _seedRow(Map<String, dynamic>.from(raw as Map)),
          conflictAlgorithm: ConflictAlgorithm.replace,
        );
      }
      batch.insert(
        'meta',
        {'key': _metaSeedVersion, 'value': bundledVersion},
        conflictAlgorithm: ConflictAlgorithm.replace,
      );
      await batch.commit(noResult: true);
    });
  }

  /// Turns one seed-JSON entry into a table row, computing the three folded
  /// search columns:
  ///   s_head  - headword + variants, as '|abi|abij|'
  ///   s_gloss - Spanish glosses (senses, phrase translations, literals),
  ///             as '|persona|el mismo|'
  ///   s_other - everything else worth matching: phrase and example text,
  ///             part-of-speech label, category, note
  /// The '|' delimiters let search tell "exactly this form" and "starts with"
  /// apart from "contains".
  Map<String, Object?> _seedRow(Map<String, dynamic> e) {
    final String brunca = e['brunca'] as String;
    final List<String> variants = List<String>.from(
      (e['variants'] as List?) ?? const [],
    );
    final List<String> senses = List<String>.from(
      (e['senses'] as List?) ?? const [],
    );
    final List<Map<String, dynamic>> examples = ((e['examples'] as List?) ??
            const [])
        .map((x) => Map<String, dynamic>.from(x as Map))
        .toList();
    final List<Map<String, dynamic>> phrases = ((e['phrases'] as List?) ??
            const [])
        .map((x) => Map<String, dynamic>.from(x as Map))
        .toList();
    final String? literal = e['literal'] as String?;

    final headForms = <String>[brunca, ...variants];
    final glossParts = <String>[
      ...senses,
      if (literal != null) literal,
      for (final p in phrases) ...[
        p['spanish'] as String,
        if (p['literal'] != null) p['literal'] as String,
      ],
    ];
    final otherParts = <String>[
      for (final p in phrases) p['brunca'] as String,
      for (final x in examples) ...[
        x['brunca'] as String,
        x['spanish'] as String,
      ],
      if (e['posLabel'] != null) e['posLabel'] as String,
      if (e['category'] != null) e['category'] as String,
      if (e['note'] != null) e['note'] as String,
    ];

    return {
      'id': e['id'] as String,
      'brunca': brunca,
      'variants': jsonEncode(variants),
      'homograph': e['homograph'] as int?,
      'pos': e['pos'] as String?,
      'posLabel': e['posLabel'] as String?,
      'senses': jsonEncode(senses),
      'literal': literal,
      'examples': jsonEncode(examples),
      'phrases': jsonEncode(phrases),
      'note': e['note'] as String?,
      'category': e['category'] as String?,
      'audioFile': e['audioFile'] as String?,
      's_head': _pipeJoin(headForms),
      's_gloss': _pipeJoin(glossParts),
      's_other': foldForSearch(otherParts.join(' ')),
    };
  }

  String _pipeJoin(List<String> parts) {
    final folded = parts
        .map(foldForSearch)
        .where((p) => p.isNotEmpty)
        .join('|');
    return '|$folded|';
  }

  // ---------------------------------------------------------------------
  // Search
  // ---------------------------------------------------------------------

  // Results are ranked, best first:
  //   0  a headword/variant equals the query
  //   1  a Spanish gloss equals the query
  //   2  a headword/variant starts with the query
  //   3  a Spanish gloss starts with the query
  //   4  headword contains the query
  //   5  gloss contains the query
  //   6  matched only in phrases, examples, part of speech, category or note
  // then alphabetically (folded), then by homograph number.
  // ESCAPE '\' lets the user type % or _ without them acting as wildcards.
  static const String _searchSql = r"""
SELECT e.*,
       (f.entry_id IS NOT NULL) AS isFavorite,
       CASE
         WHEN e.s_head  LIKE ? ESCAPE '\' THEN 0
         WHEN e.s_gloss LIKE ? ESCAPE '\' THEN 1
         WHEN e.s_head  LIKE ? ESCAPE '\' THEN 2
         WHEN e.s_gloss LIKE ? ESCAPE '\' THEN 3
         WHEN e.s_head  LIKE ? ESCAPE '\' THEN 4
         WHEN e.s_gloss LIKE ? ESCAPE '\' THEN 5
         ELSE 6
       END AS match_rank
FROM entries e
LEFT JOIN favorites f ON f.entry_id = e.id
WHERE e.s_head  LIKE ? ESCAPE '\'
   OR e.s_gloss LIKE ? ESCAPE '\'
   OR e.s_other LIKE ? ESCAPE '\'
ORDER BY match_rank, e.s_head, COALESCE(e.homograph, 0)
LIMIT ?
""";

  String _escapeLike(String s) => s
      .replaceAll(r'\', r'\\')
      .replaceAll('%', r'\%')
      .replaceAll('_', r'\_');

  /// Bidirectional search: matches Boruca headwords and variants, Spanish
  /// glosses, and (at lower rank) phrases, examples, part-of-speech labels
  /// ("verbo"), categories and notes. Accents, tone marks, ᵛ and n̈ are
  /// ignored on both sides, so a plain phone keyboard works.
  Future<List<Word>> searchWords(String query) async {
    final String folded = foldForSearch(query.replaceAll('|', ' '));
    if (folded.isEmpty) return [];
    final String q = _escapeLike(folded);

    final db = await database;
    final rows = await db.rawQuery(_searchSql, [
      '%|$q|%', // 0: headword equals
      '%|$q|%', // 1: gloss equals
      '%|$q%', // 2: headword starts with
      '%|$q%', // 3: gloss starts with
      '%$q%', // 4: headword contains
      '%$q%', // 5: gloss contains
      '%$q%', // WHERE s_head
      '%$q%', // WHERE s_gloss
      '%$q%', // WHERE s_other
      _searchLimit,
    ]);
    return rows.map((r) => Word.fromMap(r)).toList();
  }

  // ---------------------------------------------------------------------
  // Favorites
  // ---------------------------------------------------------------------

  Future<void> toggleFavorite(String id, bool isFavorite) async {
    final db = await database;
    if (isFavorite) {
      await db.insert(
        'favorites',
        {
          'entry_id': id,
          'added_at': DateTime.now().millisecondsSinceEpoch,
        },
        conflictAlgorithm: ConflictAlgorithm.ignore,
      );
    } else {
      await db.delete('favorites', where: 'entry_id = ?', whereArgs: [id]);
    }
  }

  /// Favorited entries, most recently added first.
  Future<List<Word>> getFavorites() async {
    final db = await database;
    final rows = await db.rawQuery('''
      SELECT e.*, 1 AS isFavorite
      FROM favorites f
      JOIN entries e ON e.id = f.entry_id
      ORDER BY f.added_at DESC
    ''');
    return rows.map((r) => Word.fromMap(r)).toList();
  }
}
